    once(anchor,"    if __import__('os').environ.get('CF2018_VERSION_DISCOVERY')!='YES':raise SystemExit('Explicit CF2018_VERSION_DISCOVERY=YES required')\n"+anchor)
    text=text.replace('CF2018_DIRECTORY_CONFIG','CF2018_VERSION_DISCOVERY').replace('cf2018_directory_config_runs','cf2018_version_discovery_runs')
    text=text.replace('CF2018 default startup-directory configuration control; one reply; not login','CF2018 scoped update lookup and request observation; no version reply; not login')
